  raw=m.group(0);host=re.sub(':(443|80)$','',urlsplit(raw if'://'in raw else'https://'+raw).netloc.lower());rid=m.group(1).lower();bad=None if host in('zambo.dev','www.zambo.dev')else f'foreign or lookalike host {host!r}; not fetched'
  if not bad and not RECEIPT_PATH.search(raw):continue
