def resolve_short(p,fetch=None):
 st,body=(fetch or get)(f'{Z}/api/receipts/recent?format=v2&id_prefix={p}')
 if st==404:return None,'NEED_FULL_ID',f'no receipt starts with {p}; ask for the full link'
 if st!=200:return None,'RETRY',f'id_prefix lookup HTTP {st}'
 try:o=json.loads(body)
 except ValueError:return None,'RETRY','id_prefix lookup returned non-JSON'
 rid=o.get('id')if _isd(o)else None
 if not(isinstance(rid,str)and re.fullmatch(U,rid)and rid.lower().startswith(p)):return None,'NEED_FULL_ID',f'id_prefix lookup for {p} returned an unexpected shape; ask for the full link'
