def get(url,tries=3):
 for i in range(tries):
  try:
   with urlopen(Request(url,headers=UA),timeout=20)as r:return r.status,r.read()
  except HTTPError as e:
   if e.code in(404,410,400):return e.code,e.read()
   ra=(e.headers.get('Retry-After')or'0').strip()if e.code in(429,503)else'0';wait=min(int(ra),60)if ra.isdigit()else 5;last=e.code
