def check(d,rid,fetch=get):
 if not _isd(d)or not _isd(d.get('receipt'))or not _isd(d.get('checks'))or'canonical_bytes'not in d['receipt']:return'RETRY',[f'unexpected verify response shape {CHANGED}; filed as pending, not judged'],{}
 r,why,ok,notes=d['receipt'],[],[],[]
 if _low(d,'id')!=rid or _low(r,'id')!=rid:why+=['id mismatch']
 tool=r.get('tool');tool=tool.get('name')if _isd(tool)else tool;caller,ctrl,vs=_d(r.get('caller')),CTRL.search(str(r.get('provenance_class')or'')),d.get('verification_status');sts=lambda want:[k for k,v in d['checks'].items()if _d(v).get('status')==want]
 info=lambda prov,checks,notes,inject:{'tool':tool,'created_at':r.get('created_at'),'prov':prov,'checks':checks,'notes':notes,'label':caller.get('label'),'caller_id':caller.get('id')or'','inject':inject,'free_remaining':r.get('free_remaining'),'output_hash':r.get('output_hash')}
 if r.get('canonical_bytes_withheld_for_privacy')is True and not r.get('canonical_bytes'):
  why+=[f'{k} failed'for k in sts('fail')]
  if vs not in('not_checked','withheld','verified'):why+=[f'verification_status={vs}']
  if ctrl:why+=[CTRL_MSG]
  notes='canonical bytes withheld by Zambo for privacy; hash not recomputed, not checkable';return'REJECT'if why else'WITHHELD',why,info(r.get('provenance_class'),', '.join(sts('pass')),notes,False)
 if vs!='verified':why+=[f'verification_status={vs}']
 why+=[f'{k} failed'for k in sts('fail')];ok+=sts('pass')
 if(d['checks'].get('commitment_matches')or{}).get('status')!='pass':why+=['commitment_matches not pass']
 cb={}
 try:
  raw=base64.b64decode(r['canonical_bytes'],validate=True)
  if _sha(raw)!=r.get('output_hash'):why+=['my SHA-256 of canonical_bytes != output_hash']
  else:ok+=['hash recomputed']
  cb=json.loads(raw)
  if not _isd(cb):why+=['canonical_bytes is not a JSON object'];cb={}
 except(ValueError,TypeError):why+=['canonical_bytes missing or undecodable']
 if cb and _d(cb.get('tool')).get('name')!=tool:why+=['tool in bytes != tool in metadata']
 prov=_d(cb.get('issuer_claims')).get('provenance_class')
 if cb and prov!=r.get('provenance_class'):why+=['provenance in bytes != metadata']
 if ctrl:why+=[CTRL_MSG]
 env=_d(r.get('anchor')).get('envelope')
 if _isd(env):
  if _low(env,'receipt_uuid')==rid and env.get('output_sha256')==r.get('output_hash'):ok+=['anchor envelope matches']
  else:notes+=['anchor envelope does not match this receipt (anchor not checked)']
 ev,eu=r.get('evidence_sha256'),r.get('evidence_url')or''
 if ev:
  u=urlsplit(eu);path=u.path if u.netloc in('','zambo.dev','www.zambo.dev')else''
  if path.startswith('/api/evidence/'):
   st,body=fetch(Z+path)
   if st==200 and _sha(body)==ev:ok+=['evidence matched']
   elif st==200:why+=['evidence bytes do not match evidence_sha256']
   else:notes+=[f'evidence not fetched (HTTP {st}), not checked']
  else:notes+=[f'evidence url {eu!r} not on zambo.dev, not checked']
 return'REJECT'if why else'OK',why,info(prov,', '.join(ok),'; '.join(notes),bool(INJECT.search(json.dumps(cb.get('output',''))[:4000])))
def verify(rid,fetch=get):
