CHANGED='(zambo.dev may have changed)';CTRL=re.compile(r'[\x00-\x1f\x7f]');CTRL_MSG='provenance label has control characters (AER-1 Section 5)';HO_URL=re.compile(r'zambo\.dev(?::443)?/handover/('+U+')',re.I);WF_URL=re.compile(r'(?:https?://)?(?:www\.)?zambo\.dev(?::443)?/(?:api/)?workflow/('+U+')',re.I)
