USE=set('continuity_get_recent workflow_close workflow_seal handover handover_status zambo_home day_pass_checkout_link day_pass_status day_pass_redeem pass_status activity_today'.split());BASE=HOUSE|USE|set('credithunt ghost_audit_report ghost_audit_site ghost_audit_status journal_log leadsignal live_price pdf_extract prompt_shield provibe_audit scam_check zambo_universal'.split());MERKLE_VERSIONS='receipt-id-v0','seq-output-v1'
def merkle(ids,version='receipt-id-v0',hashes=None):
 if version=='seq-output-v1':leaves=[f"{n+1}:{str(h).lower().removeprefix('sha256:')}"for n,h in enumerate(hashes or[])]
 else:leaves=list(ids)
 lv=[hashlib.sha256(i.encode()).digest()for i in leaves]
