def workflow(wid,fetch=get):
 cf=_cached(fetch);ret=lambda v,why:{**out,**_v(v,why)};out={'workflow_id':wid,'workflow_url':f'{Z}/workflow/{wid}','checked':[],'not_checked':list(NOT_CHECKED),'steps':[]};st,body=cf(f'{Z}/api/workflow/{wid}')
