 if st!=200:return ret('RETRY',f'workflow view unreachable or HTTP {st}; retry next run')
 try:v=json.loads(body)
 except ValueError:return ret('RETRY','non-JSON workflow view')
 rs=v.get('receipts')if _isd(v)else None
 if not isinstance(rs,list)or not isinstance(v.get('merkle_root'),str)or not all(_isd(x)for x in rs):return ret('RETRY',f'unexpected workflow view shape {CHANGED}; not judged')
 why,retry,held,root=[],[],[],v['merkle_root'].lower()
 if wid not in(_low(v,'id'),_low(v,'workflow_id'),_low(v,'session_workflow_id')):why+=['workflow id mismatch']
 real=str(v.get('workflow_id')or wid).lower();out.update(workflow_id=real,workflow_url=f'{Z}/workflow/{real}');ids=[_low(x,'id')for x in rs]
 if not ids:why+=['workflow has no steps']
