   c=json.loads(base64.b64decode(json.loads(cf(f'{Z}/api/v2/receipt/{cid}/verify')[1])['receipt']['canonical_bytes']));co=_d(c.get('output'));kids=[(_low(k,'id'),_low(k,'output_hash'))for k in co.get('children')or[]if _isd(k)]
