 out.update(verdict='REJECT'if why else'RETRY'if retry else'WITHHELD'if held else'OK',reasons=why+retry,count=len(ids),merkle_root=root,closed_receipt_id=cid,created_at=v.get('first_at')or'',sealed=bool(v.get('sealed')));return out
def handover(hid,fetch=get):
 st,b=fetch(f'{Z}/handover/{hid}.json');url=f'{Z}/handover/{hid}';fail=lambda v,why:{'workflow_id':hid,'workflow_url':url,'verdict':v,'reasons':[why],'checked':[],'not_checked':list(NOT_CHECKED),'steps':[]}
 if st in(404,410):return fail('REJECT',f'HTTP {st}: handover not published')
 h=_jl(b)if st==200 else None
