 r.update(handover_url=url,recipient=h.get('recipient'),goal=h.get('goal'),client_decision=h.get('status'),decided_at=h.get('decided_at'),**{'handover_'+k:h.get(k)or[]for k in('not_checked','not_run','not_proven')});r['not_checked']+=['handover steps are redacted copies (LOGGED BY AGENT) of the source receipts'];return r
