MCP=Z+'/mcp'
def _init():return _rpc('initialize',{'protocolVersion':'2025-06-18','capabilities':{},'clientInfo':{'name':'zambo-receipt-bot','version':VERSION}})
def _rpc_body(raw,ctype=''):
 t=_txt(raw)
